namespace ws {
std::string StringToLower(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), [](unsigned char c) { return std::tolower(c); });
    return str;
}

std::string StringToUpper(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), [](unsigned char c) { return std::toupper(c); });
    return str;
}

std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept {
    if (from.empty()) return std::string{str};
    std::string result;
    std::size_t start = 0;
    while (true) {
        auto pos = str.find(from, start);
        if (pos == std::string_view::npos) break;
        result.append(str.substr(start, pos - start));
        result.append(to);
        start = pos + from.size();
    }
    result.append(str.substr(start));
    return result;
}

std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) noexcept {
    std::sregex_token_iterator iter{str.begin(), str.end(), pattern, -1};
    std::sregex_token_iterator end;
    return {iter, end};
}

std::vector<std::string> SplitStringToLines(const std::string& str) noexcept {
    std::vector<std::string> lines;
    std::istringstream iss{str};
    for (std::string line; std::getline(iss, line); ) {
        lines.push_back(line);
    }
    return lines;
}

YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
    YAML::Node node = YAML::Load(std::string{str});
    for (auto field : required_fields) {
        if (!node[field]) throw std::invalid_argument{"Missing required field: " + std::string{field}};
    }
    return node;
}

void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
    auto n = node[field];
    if (!n || !n.IsScalar()) throw std::invalid_argument{"Field is not a scalar: " + std::string{field}};
}

constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept {
    return fd != invalid_file_descriptor;
}

void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) throw std::system_error{errno, std::system_category()};
}

[[noreturn]] void ThrowLastSystemError() {
    throw std::system_error{errno, std::system_category()};
}

std::uint32_t CurrentThreadId() noexcept {
    return static_cast<std::uint32_t>(syscall(SYS_gettid));
}

void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip) noexcept {
    void* buffer[size];
    auto count = backtrace(buffer, size);
    if (count <= skip) return;
    auto symbols = backtrace_symbols(buffer + skip, count - skip);
    for (std::size_t i = 0; i < count - skip; ++i) {
        stack.push_back(symbols[i]);
    }
}

std::string Backtrace(std::size_t size, std::size_t skip, std::string_view prefix) noexcept {
    std::vector<std::string> stack;
    Backtrace(stack, size, skip);
    std::ostringstream oss;
    for (const auto& frame : stack) {
        oss << prefix << frame << "\n";
    }
    return oss.str();
}

MappedReadOnlyFile::MappedReadOnlyFile() noexcept {}

MappedReadOnlyFile::MappedReadOnlyFile(MappedReadOnlyFile&& o) noexcept : path_{std::move(o.path_)}, stat_{o.stat_}, data_{o.data_} {
    o.data_ = nullptr;
}

MappedReadOnlyFile& MappedReadOnlyFile::operator=(MappedReadOnlyFile&& o) noexcept {
    if (this != &o) {
        Unmap();
        path_ = std::move(o.path_);
        stat_ = o.stat_;
        data_ = o.data_;
        o.data_ = nullptr;
    }
    return *this;
}

MappedReadOnlyFile::~MappedReadOnlyFile() noexcept {
    Unmap();
}

std::byte* MappedReadOnlyFile::Map(std::string path) {
    if (data_) throw std::runtime_error{"Already mapped"};
    path_ = std::move(path);
    if (stat(path_.c_str(), &stat_) == -1) throw std::system_error{errno, std::system_category()};
    auto fd = open(path_.c_str(), O_RDONLY);
    if (fd == invalid_file_descriptor) throw std::system_error{errno, std::system_category()};
    data_ = static_cast<std::byte*>(mmap(nullptr, stat_.st_size, PROT_READ, MAP_PRIVATE, fd, 0));
    close(fd);
    if (data_ == MAP_FAILED) {
        data_ = nullptr;
        throw std::system_error{errno, std::system_category()};
    }
    return data_;
}

void MappedReadOnlyFile::Unmap() noexcept {
    if (!data_) return;
    munmap(data_, stat_.st_size);
    data_ = nullptr;
    path_.clear();
}

std::size_t MappedReadOnlyFile::Size() const noexcept {
    return stat_.st_size;
}

std::byte* MappedReadOnlyFile::Data() const noexcept {
    return data_;
}

std::string_view MappedReadOnlyFile::Path() const noexcept {
    return path_;
}
}
